package com.bocsoft.sqleditor.execution.api;
import com.fasterxml.jackson.annotation.JsonInclude;import java.util.List;
@JsonInclude(JsonInclude.Include.NON_NULL) public class SqlExecutionResponse {private final String executionId,kind,message;private final List<SqlColumn>columns;private final List<List<Object>>rows;private final Long rowCount,affectedRows;private final Boolean truncated;private final long durationMs;
 private SqlExecutionResponse(String id,String kind,List<SqlColumn>columns,List<List<Object>>rows,Long rowCount,Long affectedRows,Boolean truncated,long duration,String message){this.executionId=id;this.kind=kind;this.columns=columns;this.rows=rows;this.rowCount=rowCount;this.affectedRows=affectedRows;this.truncated=truncated;this.durationMs=duration;this.message=message;}
 public static SqlExecutionResponse result(String id,List<SqlColumn>c,List<List<Object>>r,boolean truncated,long duration){return new SqlExecutionResponse(id,"RESULT_SET",c,r,(long)r.size(),null,truncated,duration,null);}public static SqlExecutionResponse update(String id,String kind,Long affected,long duration){return new SqlExecutionResponse(id,kind,null,null,null,affected,null,duration,"执行成功");}
 public String getExecutionId(){return executionId;}public String getKind(){return kind;}public String getMessage(){return message;}public List<SqlColumn>getColumns(){return columns;}public List<List<Object>>getRows(){return rows;}public Long getRowCount(){return rowCount;}public Long getAffectedRows(){return affectedRows;}public Boolean getTruncated(){return truncated;}public long getDurationMs(){return durationMs;}}
